INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-coe233', 'stk-mohammed_mag', 'COE 233', 'doc', '{"docs": [{"id": "stk-dr-f98318", "n": "Dr. Muhamed F. Mudawar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 233 - TERM 212 حضوري\n\nالتحضير :\nعن طريق تمرير ورقه تتمرر من بدايه الكلاس وياخذها اخر الكلاس.\n\nطريقة الشرح : الدكتور شرحه جدا واضح وجميل وأتوقع الافضل في الديبارتمنت.\n\nالكويزات :\n5 اختبارات وللأمانه جدا صعبه , سوا نورملايز بالنهايه\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات : طبعا الدكتور جدا كويس لكن الماده جدا سيئه لأنها اول مره تدرس في الترم حقنا,\nوالدكتور جدا ممتاز حتى بالاوفس اور متساعد ويفهمك المنهج كله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534500-coe233", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhamed-f-mudawar/98318/20", "user": "Mohammed_Mag", "ts": 1653828858000, "tid": 98318, "pn": 20}}]}', 1653828858000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12093-coe233', 'stk-user12093', 'COE 233', 'doc', '{"docs": [{"id": "stk-dr-f98318", "n": "Dr. Muhamed F. Mudawar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 233 - Term 212\n\nالتحضير: عبر ورقة تمر على الطلاب ويستلمها نهاية المحاضرة، يعني لو جئت أي وقت يمديك تحضّر نفسك، وأظن ما يهتم للتحضير فقط يأخذه من باب أداء الواجب.\n\nطريقة الشرح: يشرح سلايداته والتي هي سلايدات المادة العامة(مأخوذة من سلايدات COE 202 و COE 301)، شرحه واضح ومفهوم ويستقبل أسئلة الطلاب بصدر رحِب.\n\nالكويزات: اختبرنا 6 كويزات طوال الترم، تعتبر متوسطة، وغالبها من اختبارات الفصول الدراسية السابقة(old exams).\n\nالمياجر: اختبار نصفي(Midterm Exam) ومشترك.\n\nالفاينلات: مشترك.\n\nالقريد النهائي: A.\n\nالصوت: واضح ومفهوم بلكنة شامية.\n\nإضافات: عادة التأخير في المحاضرة وأخذ وقت زيادة لا تزال موجودة-كما في تقييم الشباب فوق-لكن ليس لها كبير أثر، تصحيح الدكتور كويس واختباراته عادة تكون متكررة في غالب الأسئلة ويكفيك أدنى إطلاع على الاختبارات التي كان فيها هو الكوردنيتر. لو المادة عن computer architecture فأنصحك تنزل عنده لكونه يعتبر من اهتمامات الدكتور وتخصصه الدقيق وفاهم فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534514-coe233", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhamed-f-mudawar/98318/21", "user": "user12093", "ts": 1653903732000, "tid": 98318, "pn": 21}}]}', 1653903732000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
